// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  const discounted = subtotal * (1 - discount) * (1 - bulk);
  return Math.round(discounted * (1 - discount));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
import { total } from './cart.js';

// Invoices for wholesale orders (#7). The amount due is the cart total as it is:
// wholesale customers order from a printed price list that follows the same rules —
// list price below 10 lines, 5% off from 10 lines, half a yen rounded up.
export function invoice(customer, items) {
  return { customer, due: total(items) };
}
---
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { invoice } from '../src/invoice.js';

test('a wholesale order below 10 lines is invoiced at list price', () => {
  const order = [{ price: 100, qty: 2 }, { price: 50, qty: 1 }, { price: 30, qty: 1 }];
  assert.equal(invoice('acme', order).due, 280);
});

test('a wholesale order of 10 lines gets 5% off, half a yen rounded up', () => {
  const order = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(invoice('acme', order).due, 105); // 110 * 0.95 = 104.5, as on the price list
});

# お客さまの割引が二重にかかっている

お客さまの割引とまとめ買い割引の組み合わせで、カートの合計が決めた仕様と合っていません。`src/cart.js` の `total` を直してください。

